import json, os, math
base='/work/inputs'
with open(os.path.join(base,'inputs.json')) as f:
    mapping=json.load(f)
print('mapping', mapping)

def load(mid):
    fn=mapping[mid]
    path=os.path.join(base, fn) if not os.path.isabs(fn) else fn
    with open(path) as f:
        return json.load(f)

def find_series(obj):
    # return longest list of numbers found
    best=[]
    def rec(o):
        nonlocal best
        if isinstance(o, list):
            if o and all(isinstance(x,(int,float)) for x in o):
                if len(o)>len(best):
                    best=o[:]
            else:
                for x in o: rec(x)
        elif isinstance(o, dict):
            for v in o.values(): rec(v)
    rec(obj)
    return best

data=load('m_1be11d9054d7')
